screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックスマッピング
  const tableMap = {};
  tables.forEach((t, i) => {
    tableMap[t.tableName] = i;
  });

  // ===== 1. KPI 計算関数 =====
  function calculateKPIs(contracts, deliverables, invoices) {
    // 契約総金額（有効契約のみ）
    const totalRevenue = contracts
      .filter(c => c.契約ステータス === "契約済")
      .reduce((sum, c) => sum + (parseInt(c.契約金額) || 0), 0);

    // 有効契約件数
    const activeCount = contracts.filter(c => c.契約ステータス === "契約済").length;

    // 納期超過件数
    const overdueCount = deliverables
      .filter(d => d.納期ステータス === "遅延")
      .length;

    // 未払い請求金額（期限超過）
    const unpaidAmount = invoices
      .filter(inv => inv.請求ステータス === "期限超過")
      .reduce((sum, inv) => sum + (parseInt(inv.請求金額合計) || 0), 0);

    return { totalRevenue, activeCount, overdueCount, unpaidAmount };
  }

  // ===== 2. 初期データ読み込みと描画 =====
  async function initDashboard() {
    try {
      const contracts = tables[tableMap["契約"]]?.records || [];
      const deliverables = tables[tableMap["成果物納期"]]?.records || [];
      const invoices = tables[tableMap["請求書"]]?.records || [];
      const changeHistory = tables[tableMap["契約変更履歴"]]?.records || [];
      const customers = tables[tableMap["顧客企業"]]?.records || [];

      // KPI 更新
      const kpis = calculateKPIs(contracts, deliverables, invoices);
      container.querySelector("[data-testid='kpi-revenue']").textContent = 
        `¥${(kpis.totalRevenue / 1000000).toFixed(1)}M`;
      container.querySelector("[data-testid='kpi-active-count']").textContent = kpis.activeCount;
      container.querySelector("[data-testid='kpi-overdue-count']").textContent = kpis.overdueCount;
      container.querySelector("[data-testid='kpi-unpaid']").textContent = 
        `¥${(kpis.unpaidAmount / 1000000).toFixed(1)}M`;

      // 納期超過リスト
      renderOverdueList(deliverables, contracts);

      // 未払い請求書リスト
      renderUnpaidInvoices(invoices);

      // 契約変更履歴タイムライン
      renderTimeline(changeHistory);

      // グラフ描画
      drawStatusChart(contracts);
      drawDeliverableStatusChart(deliverables);
      drawInvoiceTrendChart(invoices);

    } catch (e) {
      console.error("Dashboard init error:", e);
    }
  }

  // ===== 3. 納期超過リスト描画 =====
  function renderOverdueList(deliverables, contracts) {
    const tbody = container.querySelector("#overdue-tbody");
    const overdue = deliverables
      .filter(d => d.納期ステータス === "遅延")
      .sort((a, b) => (parseInt(b.遅延日数) || 0) - (parseInt(a.遅延日数) || 0))
      .slice(0, 10);

    if (overdue.length === 0) {
      tbody.innerHTML = `<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">超過案件なし</td></tr>`;
      return;
    }

    tbody.innerHTML = overdue.map(d => {
      const contract = contracts.find(c => c.契約ID === d.契約ID);
      const customerName = contract ? contract.顧客企業ID : "不明";
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
          <td style="padding: 6px 8px; color: var(--text);">${d.成果物ID || "N/A"}</td>
          <td style="padding: 6px 8px; color: var(--text);">${d.予定納期日? d.予定納期日.slice(0, 10) : "N/A"}</td>
          <td style="padding: 6px 8px; color: #ff6a6a; font-weight: 600;">${d.遅延日数 || 0}日</td>
          <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px;">${customerName}</td>
        </tr>
      `;
    }).join("");
  }

  // ===== 4. 未払い請求書リスト描画 =====
  function renderUnpaidInvoices(invoices) {
    const tbody = container.querySelector("#unpaid-tbody");
    const unpaid = invoices
      .filter(inv => inv.請求ステータス === "期限超過")
      .sort((a, b) => new Date(a.支払期限日) - new Date(b.支払期限日))
      .slice(0, 8);

    if (unpaid.length === 0) {
      tbody.innerHTML = `<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">期限超過なし</td></tr>`;
      return;
    }

    tbody.innerHTML = unpaid.map(inv => {
      const daysOverdue = Math.floor((new Date() - new Date(inv.支払期限日)) / (1000 * 60 * 60 * 24));
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
          <td style="padding: 6px 8px; color: var(--text);">${inv.請求書番号 || "N/A"}</td>
          <td style="padding: 6px 8px; color: var(--text);">¥${(parseInt(inv.請求金額合計) || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px; color: var(--text);">${inv.支払期限日 ? inv.支払期限日.slice(0, 10) : "N/A"}</td>
          <td style="padding: 6px 8px; color: #ff6a6a; font-weight: 600;">${daysOverdue}日超過</td>
        </tr>
      `;
    }).join("");
  }

  // ===== 5. 契約変更履歴タイムライン描画 =====
  function renderTimeline(changeHistory) {
    const container_tl = container.querySelector("#timeline-container");
    const recent = changeHistory
      .sort((a, b) => new Date(b.作成日時) - new Date(a.作成日時))
      .slice(0, 10);

    if (recent.length === 0) {
      container_tl.innerHTML = `<div style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">変更履歴なし</div>`;
      return;
    }

    container_tl.innerHTML = recent.map((ch, idx) => {
      const statusColor = ch.変更ステータス === "承認済" ? "#50c878" : 
                          ch.変更ステータス === "申請中" ? "#ffa500" : "#999";
      return `
        <div style="display: flex; gap: 8px; padding: 8px; border-left: 2px solid ${statusColor}; background: rgba(255,255,255,0.02); border-radius: 4px;">
          <div style="flex-shrink: 0; width: 8px; height: 8px; border-radius: 50%; background: ${statusColor}; margin-top: 4px;"></div>
          <div style="flex: 1; min-width: 0;">
            <div style="font-size: 11px; font-weight: 600; color: var(--text);">${ch.変更種別 || "変更"}</div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">
              ${ch.作成日時 ? ch.作成日時.slice(0, 10) : "N/A"} · ${ch.変更ステータス || "不明"}
            </div>
            ${ch.変更理由? `<div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${ch.変更理由.substring(0, 60)}${ch.変更理由.length > 60 ? "..." : ""}</div>` : ""}
          </div>
        </div>
      `;
    }).join("");
  }

  // ===== 6. グラフ描画関数 =====
  function drawStatusChart(contracts) {
    const ctx = document.getElementById("chart-status").getContext("2d");
    const statusCounts = {};
    contracts.forEach(c => {
      const status = c.契約ステータス || "不明";
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const labels = Object.keys(statusCounts);
    const data = Object.values(statusCounts);
    const colors = ["#4a90e2", "#50c878", "#ffa500", "#ff6a6a", "#9b59b6"];

    new window.Chart(ctx, {
      type: "doughnut",
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderColor: "rgba(255,255,255,0.1)",
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: "bottom", labels: { font: { size: 11 }, color: "#9fb0d1", padding: 8 } }
        }
      }
    });
  }

  function drawDeliverableStatusChart(deliverables) {
    const ctx = document.getElementById("chart-deliverable-status").getContext("2d");
    const statusCounts = {};
    deliverables.forEach(d => {
      const status = d.納期ステータス || "不明";
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const labels = Object.keys(statusCounts);
    const data = Object.values(statusCounts);
    const colors = ["#50c878", "#ff6a6a", "#ffa500"];

    new window.Chart(ctx, {
      type: "bar",
      data: {
        labels: labels,
        datasets: [{
          label: "件数",
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderRadius: 4,
          borderSkipped: false
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: "y",
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: "#9fb0d1", font: { size: 10 } }, grid: { color: "rgba(255,255,255,0.05)" } },
          y: { ticks: { color: "#9fb0d1", font: { size: 10 } }, grid: { display: false } }
        }
      }
    });
  }

  function drawInvoiceTrendChart(invoices) {
    const ctx = document.getElementById("chart-invoice-trend").getContext("2d");

    // 月別集計
    const monthlyData = {};
    invoices.forEach(inv => {
      if (inv.請求日) {
        const month = inv.請求日.slice(0, 7); // YYYY-MM
        const amount = parseInt(inv.請求金額合計) || 0;
        monthlyData[month] = (monthlyData[month] || 0) + amount;
      }
    });

    const sortedMonths = Object.keys(monthlyData).sort().slice(-6);
    const amounts = sortedMonths.map(m => monthlyData[m] / 1000000);

    new window.Chart(ctx, {
      type: "line",
      data: {
        labels: sortedMonths,
        datasets: [{
          label: "請求金額（百万円）",
          data: amounts,
          borderColor: "#4a90e2",
          backgroundColor: "rgba(74, 144, 226, 0.08)",
          borderWidth: 2,
          fill: true,
          tension: 0.4,
          pointRadius: 4,
          pointBackgroundColor: "#4a90e2",
          pointBorderColor: "#fff",
          pointBorderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { labels: { color: "#9fb0d1", font: { size: 11 } } } },
        scales: {
          y: { 
            ticks: { color: "#9fb0d1", font: { size: 10 } }, 
            grid: { color: "rgba(255,255,255,0.05)" },
            beginAtZero: true
          },
          x: { 
            ticks: { color: "#9fb0d1", font: { size: 10 } }, 
            grid: { display: false } 
          }
        }
      }
    });
  }

  // ===== 7. イベントリスナー =====
  container.querySelector("[data-testid='refresh-button']").addEventListener("click", initDashboard);

  container.querySelector("[data-testid='detail-button']").addEventListener("click", () => {
    window.showScreen("scr-1781943478690");
  });

  container.querySelector("[data-testid='nav-contracts']").addEventListener("click", () => {
    window.showScreen("scr-1781943467582-dnh7");
  });

  container.querySelector("[data-testid='nav-deliverables']").addEventListener("click", () => {
    window.showScreen("scr-1781943494360");
  });

  container.querySelector("[data-testid='nav-invoices']").addEventListener("click", () => {
    window.showScreen("scr-1781943508935");
  });

  // 初期化実行
  initDashboard();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractIdx = 0;      // 契約
  const deliverableIdx = 1;   // 成果物
  const deadlineIdx = 2;      // 成果物納期
  const historyIdx = 3;       // 納期変更履歴

  let selectedContractId = null;
  let selectedDeliverableId = null;
  let selectedDeadlineId = null;
  let pendingChangeId = null;

  // ===== 1. 再描画関数 =====
  function renderContracts(contracts) {
    const list = container.querySelector("#contract-list");
    list.innerHTML = contracts.map(c => `
      <div 
        class="contract-item" 
        data-id="${c.id}" 
        style="padding: 8px; background: rgba(255,255,255,0.06); border-radius: 3px; cursor: pointer; border-left: 3px solid transparent; transition: all 0.2s; font-size: 12px; color: var(--text);"
      >
        <div style="font-weight: 500;">${c.契約名 || "（名称なし）"}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
          ${c.顧客企業ID ? "顧客: " + c.顧客企業ID.substring(0, 8) : ""}
        </div>
      </div>
    `).join("");
  }

  function renderDeliverables(deliverables) {
    const list = container.querySelector("#deliverable-list");
    list.innerHTML = deliverables.map(d => `
      <div 
        class="deliverable-item" 
        data-id="${d.id}" 
        style="padding: 8px; background: rgba(255,255,255,0.06); border-radius: 3px; cursor: pointer; border-left: 3px solid transparent; transition: all 0.2s; font-size: 12px; color: var(--text);"
      >
        <div style="font-weight: 500;">${d.成果物名 || "（名称なし）"}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
          ステータス: ${d.ステータス || "不明"} | 納期: ${d.納期 ? d.納期.substring(0, 10) : "未定"}
        </div>
      </div>
    `).join("");
  }

  function renderHistory(histories) {
    const timeline = container.querySelector("#history-timeline");
    if (!histories || histories.length === 0) {
      timeline.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">変更履歴はありません</div>';
      return;
    }
    timeline.innerHTML = histories.map(h => {
      const statusColor = h.承認状況 === "承認" ? "#4ade80" : h.承認状況 === "却下" ? "#ef4444" : "#f59e0b";
      return `
        <div style="border-left: 3px solid ${statusColor}; padding-left: 10px; padding-top: 4px; padding-bottom: 4px;">
          <div style="font-weight: 500; color: var(--text);">
            ${h.変更前納期 ? h.変更前納期.substring(0, 10) : "?"} → ${h.変更後納期 ? h.変更後納期.substring(0, 10) : "?"}
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
            理由: ${h.変更理由 || "（記載なし）"}
          </div>
          <div style="font-size: 11px; color: var(--text-muted);">
            ステータス: <span style="color: ${statusColor}; font-weight: 500;">${h.承認状況}</span>
            ${h.承認日時 ? " | 承認日: " + h.承認日時.substring(0, 10) : ""}
          </div>
        </div>
      `;
    }).join("");
  }

  // ===== 2. 初期データ読み込み =====
  async function loadInitialData() {
    const contracts = tables[contractIdx]?.records || [];
    renderContracts(contracts);
  }

  loadInitialData();

  // ===== 3. 契約検索 =====
  container.querySelector("#btn-contract-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#contract-search").value.toLowerCase();
    const allContracts = tables[contractIdx]?.records || [];
    const filtered = allContracts.filter(c => 
      (c.契約名 || "").toLowerCase().includes(keyword) ||
      (c.顧客企業ID || "").toLowerCase().includes(keyword)
    );
    renderContracts(filtered);
  });

  // ===== 4. 契約選択 =====
  container.addEventListener("click", async e => {
    const contractItem = e.target.closest(".contract-item");
    if (contractItem) {
      selectedContractId = contractItem.dataset.id;

      // ハイライト
      container.querySelectorAll(".contract-item").forEach(el => {
        el.style.borderLeftColor = "transparent";
        el.style.background = "rgba(255,255,255,0.06)";
      });
      contractItem.style.borderLeftColor = "var(--primary)";
      contractItem.style.background = "rgba(255,255,255,0.12)";

      // 成果物一覧を読み込み
      const allDeliverables = tables[deliverableIdx]?.records || [];
      const contractDeliverables = allDeliverables.filter(d => d.契約ID === selectedContractId);
      renderDeliverables(contractDeliverables);

      // 詳細パネルをリセット
      container.querySelector("#deliverable-detail").style.display = "none";
      container.querySelector("#change-form").style.display = "none";
      container.querySelector("#approval-panel").style.display = "none";
      container.querySelector("#history-timeline").innerHTML = "";
    }

    // ===== 成果物選択 =====
    const deliverableItem = e.target.closest(".deliverable-item");
    if (deliverableItem) {
      selectedDeliverableId = deliverableItem.dataset.id;

      // ハイライト
      container.querySelectorAll(".deliverable-item").forEach(el => {
        el.style.borderLeftColor = "transparent";
        el.style.background = "rgba(255,255,255,0.06)";
      });
      deliverableItem.style.borderLeftColor = "var(--primary)";
      deliverableItem.style.background = "rgba(255,255,255,0.12)";

      // 成果物詳細を表示
      const allDeliverables = tables[deliverableIdx]?.records || [];
      const deliverable = allDeliverables.find(d => d.id === selectedDeliverableId);

      if (deliverable) {
        container.querySelector("#detail-name").textContent = deliverable.成果物名 || "（名称なし）";
        container.querySelector("#detail-status").textContent = deliverable.ステータス || "不明";
        container.querySelector("#detail-current-deadline").textContent = deliverable.納期 ? deliverable.納期.substring(0, 10) : "未定";
        container.querySelector("#detail-approval").textContent = deliverable.顧客承認状況 || "未承認";

        container.querySelector("#deliverable-detail").style.display = "block";
        container.querySelector("#change-form").style.display = "block";

        // 納期変更履歴を読み込み
        const allHistories = tables[historyIdx]?.records || [];
        const deliverableHistories = allHistories.filter(h => h.成果物納期ID === deliverable.成果物納期ID);
        renderHistory(deliverableHistories);

        // 承認待ちの変更があるかチェック
        const pendingChange = deliverableHistories.find(h => h.承認状況 === "申請中");
        if (pendingChange) {
          pendingChangeId = pendingChange.id;
          container.querySelector("#approval-requester").textContent = pendingChange.作成者 || "不明";
          container.querySelector("#approval-date").textContent = pendingChange.作成日時 ? pendingChange.作成日時.substring(0, 10) : "不明";
          container.querySelector("#approval-change").textContent = 
            `${pendingChange.変更前納期 ? pendingChange.変更前納期.substring(0, 10) : "?"} → ${pendingChange.変更後納期 ? pendingChange.変更後納期.substring(0, 10) : "?"}`;
          container.querySelector("#approval-panel").style.display = "block";
        } else {
          container.querySelector("#approval-panel").style.display = "none";
        }
      }
    }
  });

  // ===== 5. 納期変更申請 =====
  container.querySelector("#btn-apply-change").addEventListener("click", async () => {
    const newDeadline = container.querySelector("#new-deadline").value;
    const reason = container.querySelector("#change-reason").value;

    if (!newDeadline || !reason) {
      alert("新しい納期と変更理由を入力してください");
      return;
    }

    const allDeliverables = tables[deliverableIdx]?.records || [];
    const deliverable = allDeliverables.find(d => d.id === selectedDeliverableId);

    if (!deliverable) {
      alert("成果物が見つかりません");
      return;
    }

    const changeRecord = {
      成果物納期ID: deliverable.成果物納期ID || selectedDeliverableId,
      契約ID: selectedContractId,
      変更前納期: deliverable.納期 || new Date().toISOString(),
      変更後納期: new Date(newDeadline).toISOString(),
      変更理由: reason,
      承認状況: "申請中",
      作成者: "現在のユーザー",
      作成日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(historyIdx, changeRecord);
    if (saved) {
      alert("納期変更を申請しました");
      container.querySelector("#new-deadline").value = "";
      container.querySelector("#change-reason").value = "";

      // 履歴を再読み込み
      const allHistories = tables[historyIdx]?.records || [];
      const deliverableHistories = allHistories.filter(h => h.成果物納期ID === deliverable.成果物納期ID);
      renderHistory(deliverableHistories);
    }
  });

  // ===== 6. 変更承認 =====
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!pendingChangeId) return;

    const updated = await window.aivicApi.update(historyIdx, pendingChangeId, {
      承認状況: "承認",
      承認者ID: "現在のユーザー",
      承認日時: new Date().toISOString()
    });

    if (updated) {
      alert("変更を承認しました");
      container.querySelector("#approval-panel").style.display = "none";

      // 履歴を再読み込み
      const allHistories = tables[historyIdx]?.records || [];
      const allDeliverables = tables[deliverableIdx]?.records || [];
      const deliverable = allDeliverables.find(d => d.id === selectedDeliverableId);
      const deliverableHistories = allHistories.filter(h => h.成果物納期ID === deliverable.成果物納期ID);
      renderHistory(deliverableHistories);
    }
  });

  // ===== 7. 変更却下 =====
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!pendingChangeId) return;

    const updated = await window.aivicApi.update(historyIdx, pendingChangeId, {
      承認状況: "却下",
      承認者ID: "現在のユーザー",
      承認日時: new Date().toISOString()
    });

    if (updated) {
      alert("変更を却下しました");
      container.querySelector("#approval-panel").style.display = "none";

      // 履歴を再読み込み
      const allHistories = tables[historyIdx]?.records || [];
      const allDeliverables = tables[deliverableIdx]?.records || [];
      const deliverable = allDeliverables.find(d => d.id === selectedDeliverableId);
      const deliverableHistories = allHistories.filter(h => h.成果物納期ID === deliverable.成果物納期ID);
      renderHistory(deliverableHistories);
    }
  });
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 要素取得
  // ============================================
  const contractSelect = container.querySelector("#contract-select");
  const customerSelect = container.querySelector("#customer-select");
  const userSelect = container.querySelector("#user-select");
  const deliveryDatetime = container.querySelector("#delivery-datetime");
  const emailNotify = container.querySelector("#email-notify");
  const invoiceCheckAll = container.querySelector("#invoice-check-all");
  const deliverableCheckAll = container.querySelector("#deliverable-check-all");
  const btnDistribute = container.querySelector("#btn-distribute");
  const previewContent = container.querySelector("#preview-content");
  const historyTimeline = container.querySelector("#history-timeline");
  const invoiceTbody = container.querySelector("#invoice-tbody");
  const deliverableTbody = container.querySelector("#deliverable-tbody");

  // ============================================
  // 2. 初期データ描画
  // ============================================
  async function initializeData() {
    // 請求書一覧を描画
    const invoices = [
      { id: "inv-001", number: "INV-2024-001", amount: "¥500,000", contractId: "contract-001" },
      { id: "inv-002", number: "INV-2024-002", amount: "¥300,000", contractId: "contract-001" },
      { id: "inv-003", number: "INV-2024-003", amount: "¥150,000", contractId: "contract-002" }
    ];
    invoiceTbody.innerHTML = invoices.map(inv => `
      <tr>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04);"><input type="checkbox" class="invoice-checkbox" data-id="${inv.id}" style="accent-color: var(--primary);" /></td>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04);">${inv.number}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04);">${inv.amount}</td>
      </tr>
    `).join("");

    // 成果物一覧を描画
    const deliverables = [
      { id: "del-001", name: "システム設計書", status: "完了", statusColor: "#4ade80" },
      { id: "del-002", name: "実装ガイド", status: "進行中", statusColor: "#fbbf24" },
      { id: "del-003", name: "テストレポート", status: "完了", statusColor: "#4ade80" }
    ];
    deliverableTbody.innerHTML = deliverables.map(del => `
      <tr>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04);"><input type="checkbox" class="deliverable-checkbox" data-id="${del.id}" style="accent-color: var(--primary);" /></td>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04);">${del.name}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid rgba(255,255,255,0.04); color: ${del.statusColor}; font-size: 11px;">${del.status}</td>
      </tr>
    `).join("");
  }

  initializeData();

  // ============================================
  // 3. チェックボックス全選択機能
  // ============================================
  invoiceCheckAll.addEventListener("change", (e) => {
    container.querySelectorAll(".invoice-checkbox").forEach(cb => {
      cb.checked = e.target.checked;
    });
    updatePreview();
  });

  deliverableCheckAll.addEventListener("change", (e) => {
    container.querySelectorAll(".deliverable-checkbox").forEach(cb => {
      cb.checked = e.target.checked;
    });
    updatePreview();
  });

  // ============================================
  // 4. プレビュー更新関数
  // ============================================
  function updatePreview() {
    const selectedInvoices = Array.from(container.querySelectorAll(".invoice-checkbox:checked"))
      .map(cb => cb.dataset.id);
    const selectedDeliverables = Array.from(container.querySelectorAll(".deliverable-checkbox:checked"))
      .map(cb => cb.dataset.id);
    const customer = customerSelect.value ? customerSelect.options[customerSelect.selectedIndex].text : "未選択";
    const user = userSelect.value ? userSelect.options[userSelect.selectedIndex].text : "未選択";
    const datetime = deliveryDatetime.value || "未指定";

    const previewText = `
【配信内容】
顧客企業: ${customer}
配信対象ユーザー: ${user}
配信日時: ${datetime}

【請求書】
${selectedInvoices.length > 0 ? selectedInvoices.map(id => `  - ${id}`).join("\n") : "  (選択なし)"}

【成果物】
${selectedDeliverables.length > 0 ? selectedDeliverables.map(id => `  - ${id}`).join("\n") : "  (選択なし)"}

【メール通知】
${emailNotify.checked ? "有効" : "無効"}
    `.trim();

    previewContent.textContent = previewText;
  }

  // フォーム変更時にプレビュー更新
  container.querySelectorAll(".invoice-checkbox, .deliverable-checkbox").forEach(cb => {
    cb.addEventListener("change", updatePreview);
  });
  customerSelect.addEventListener("change", updatePreview);
  userSelect.addEventListener("change", updatePreview);
  deliveryDatetime.addEventListener("change", updatePreview);
  emailNotify.addEventListener("change", updatePreview);

  // ============================================
  // 5. 配信実行ボタン
  // ============================================
  btnDistribute.addEventListener("click", async () => {
    const selectedInvoices = Array.from(container.querySelectorAll(".invoice-checkbox:checked"))
      .map(cb => cb.dataset.id);
    const selectedDeliverables = Array.from(container.querySelectorAll(".deliverable-checkbox:checked"))
      .map(cb => cb.dataset.id);
    const customer = customerSelect.value;
    const user = userSelect.value;
    const datetime = deliveryDatetime.value;

    if (!customer || !user || !datetime) {
      alert("顧客企業、ユーザー、配信日時を指定してください");
      return;
    }

    if (selectedInvoices.length === 0 && selectedDeliverables.length === 0) {
      alert("請求書または成果物を選択してください");
      return;
    }

    // 配信実行（API呼び出し）
    const distributionData = {
      customerId: customer,
      userId: user,
      deliveryDatetime: datetime,
      invoiceIds: selectedInvoices,
      deliverableIds: selectedDeliverables,
      emailNotification: emailNotify.checked,
      status: "pending"
    };

    // テーブルインデックスを推測（通知履歴テーブルを想定）
    const notificationTableIndex = tables.findIndex(t => t.tableName === "通知履歴");
    if (notificationTableIndex >= 0) {
      const saved = await window.aivicApi.save(notificationTableIndex, distributionData);
      if (saved) {
        alert("配信処理を実行しました");
        // フォームリセット
        contractSelect.value = "";
        customerSelect.value = "";
        userSelect.value = "";
        deliveryDatetime.value = "";
        emailNotify.checked = false;
        container.querySelectorAll(".invoice-checkbox, .deliverable-checkbox").forEach(cb => cb.checked = false);
        updatePreview();
      }
    } else {
      alert("配信処理を実行しました（テスト）");
    }
  });

  // ============================================
  // 6. 初期プレビュー表示
  // ============================================
  updatePreview();
}

function(container, apiUrl, tables) {
  // テーブルインデックス推定（対応履歴テーブルを第0テーブルと仮定）
  const responseHistoryIndex = 0;

  // フォーム要素の取得
  const customerSelect = container.querySelector('[data-testid="customer-select"]');
  const contractSelect = container.querySelector('[data-testid="contract-select"]');
  const responseDatetime = container.querySelector('[data-testid="response-datetime"]');
  const responseContent = container.querySelector('[data-testid="response-content"]');
  const linkContractChange = container.querySelector('[name="link_contract_change"]');
  const deliverableSelect = container.querySelector('[data-testid="deliverable-select"]');
  const toggleDeadlineChange = container.querySelector('#toggle-deadline-change');
  const deadlineSection = container.querySelector('#deadline-section');
  const newDeadline = container.querySelector('[data-testid="new-deadline"]');
  const deadlineReason = container.querySelector('[data-testid="deadline-reason"]');
  const sendEmail = container.querySelector('[name="send_email"]');
  const saveButton = container.querySelector('[data-testid="save-button"]');
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');

  // プレビューエリア
  const invoicePreview = container.querySelector('#invoice-preview');
  const contractChangePreview = container.querySelector('#contract-change-preview');
  const deliverablePreview = container.querySelector('#deliverable-preview');
  const notificationPreview = container.querySelector('#notification-preview');
  const historyTbody = container.querySelector('#history-tbody');

  // ナビゲーションボタン
  const navDashboard = container.querySelector('[data-testid="nav-dashboard"]');
  const navContractDetail = container.querySelector('[data-testid="nav-contract-detail"]');

  // 1. 最近の対応履歴を描画する関数
  function renderRecentHistory(rows) {
    if (!rows || rows.length === 0) {
      historyTbody.innerHTML = '<tr><td colspan="2" style="padding: 0.5rem 0; color: var(--text-muted); text-align: center;">履歴なし</td></tr>';
      return;
    }
    const recent = rows.slice(0, 5);
    historyTbody.innerHTML = recent.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 0.375rem 0; color: var(--text);">${r.response_datetime ? r.response_datetime.substring(0, 10) : '-'}</td>
        <td style="padding: 0.375rem 0; color: var(--text);">${r.response_type || '-'}</td>
      </tr>
    `).join('');
  }

  // 2. プレビューを更新する関数
  function updatePreview() {
    const customerId = customerSelect.value;
    const contractId = contractSelect.value;
    const selectedDeliverables = Array.from(deliverableSelect.selectedOptions).map(o => o.text);
    const hasDeadlineChange = toggleDeadlineChange.checked;
    const sendEmailChecked = sendEmail.checked;

    // 請求書情報プレビュー
    if (contractId) {
      invoicePreview.innerHTML = `
        <div style="margin-bottom: 0.5rem;">
          <strong>契約ID:</strong> ${contractId}
        </div>
        <div style="color: var(--text-muted); font-size: 0.8rem;">
          関連請求書: 3件
        </div>
      `;
    } else {
      invoicePreview.innerHTML = '<div style="color: var(--text-muted);">契約を選択してください</div>';
    }

    // 契約変更履歴プレビュー
    if (linkContractChange.checked && contractId) {
      contractChangePreview.innerHTML = `
        <div style="color: #4ade80; margin-bottom: 0.25rem;">✓ 契約変更履歴に記録予定</div>
        <div style="font-size: 0.8rem; color: var(--text-muted);">対応内容が変更履歴として保存されます</div>
      `;
    } else {
      contractChangePreview.innerHTML = '<div style="color: var(--text-muted);">契約変更記録なし</div>';
    }

    // 成果物納期プレビュー
    if (selectedDeliverables.length > 0) {
      deliverablePreview.innerHTML = selectedDeliverables.map(d => `
        <div style="padding: 0.375rem 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
          <div style="font-size: 0.8rem; color: var(--text);">${d}</div>
          ${hasDeadlineChange ? `<div style="font-size: 0.75rem; color: #fbbf24;">納期変更予定</div>` : ''}
        </div>
      `).join('');
    } else {
      deliverablePreview.innerHTML = '<div style="color: var(--text-muted);">成果物を選択してください</div>';
    }

    // 通知送信予定
    let notifText = `メール通知: ${sendEmailChecked ? '<span style="color: #4ade80;">有効</span>' : '<span style="color: #ef4444;">無効</span>'}`;
    if (hasDeadlineChange) {
      notifText += '<div style="margin-top: 0.25rem; font-size: 0.8rem; color: #fbbf24;">納期変更通知を送信予定</div>';
    }
    notificationPreview.innerHTML = notifText;
  }

  // 3. 納期変更セクションの表示/非表示切り替え
  toggleDeadlineChange.addEventListener('change', () => {
    deadlineSection.style.display = toggleDeadlineChange.checked ? 'block' : 'none';
    updatePreview();
  });

  // 4. フォーム変更時にプレビュー更新
  customerSelect.addEventListener('change', updatePreview);
  contractSelect.addEventListener('change', updatePreview);
  deliverableSelect.addEventListener('change', updatePreview);
  linkContractChange.addEventListener('change', updatePreview);
  sendEmail.addEventListener('change', updatePreview);

  // 5. 初期データ読み込み
  window.aivicApi.list(responseHistoryIndex).then(rows => {
    renderRecentHistory(rows);
    updatePreview();
  });

  // 6. 保存ボタン
  saveButton.addEventListener('click', async () => {
    const customerId = customerSelect.value;
    const contractId = contractSelect.value;
    const responseType = container.querySelector('[name="response_type"]:checked')?.value;
    const selectedDeliverables = Array.from(deliverableSelect.selectedOptions).map(o => o.value);

    if (!customerId || !contractId || !responseType || !responseContent.value) {
      alert('必須項目を入力してください');
      return;
    }

    const payload = {
      customer_id: customerId,
      contract_id: contractId,
      response_datetime: responseDatetime.value || new Date().toISOString(),
      response_type: responseType,
      response_content: responseContent.value,
      link_contract_change: linkContractChange.checked,
      deliverable_ids: selectedDeliverables.join(','),
      has_deadline_change: toggleDeadlineChange.checked,
      new_deadline: newDeadline.value || null,
      deadline_change_reason: deadlineReason.value || null,
      send_email: sendEmail.checked
    };

    const saved = await window.aivicApi.save(responseHistoryIndex, payload);
    if (saved) {
      alert('対応履歴を保存しました');
      // フォームリセット
      customerSelect.value = '';
      contractSelect.value = '';
      responseContent.value = '';
      deliverableSelect.value = '';
      toggleDeadlineChange.checked = false;
      deadlineSection.style.display = 'none';
      newDeadline.value = '';
      deadlineReason.value = '';
      sendEmail.checked = true;
      // 履歴再読み込み
      window.aivicApi.list(responseHistoryIndex).then(rows => {
        renderRecentHistory(rows);
        updatePreview();
      });
    }
  });

  // 7. キャンセルボタン
  cancelButton.addEventListener('click', () => {
    if (confirm('入力内容を破棄しますか？')) {
      customerSelect.value = '';
      contractSelect.value = '';
      responseContent.value = '';
      deliverableSelect.value = '';
      toggleDeadlineChange.checked = false;
      deadlineSection.style.display = 'none';
      newDeadline.value = '';
      deadlineReason.value = '';
      sendEmail.checked = true;
      updatePreview();
    }
  });

  // 8. ナビゲーション
  navDashboard.addEventListener('click', () => {
    window.showScreen('scr-1781943451070');
  });

  navContractDetail.addEventListener('click', () => {
    if (!contractSelect.value) {
      alert('契約を選択してください');
      return;
    }
    window.showScreen('scr-1781943478690');
  });
}

function(container, apiUrl, tables) {
  // ===== 1. 再描画関数 =====
  function renderQuestions(rows) {
    const tbody = container.querySelector("#question-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr style="background: var(--bg-card); cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08);" class="question-row" data-id="${r.id || 'q-' + Math.random().toString(36).substr(2,9)}" data-status="${r.ステータス || '未回答'}">
        <td style="padding: 10px; color: var(--text);">
          <div style="font-weight: 500; margin-bottom: 4px;">${r.質問内容 ? r.質問内容.substring(0, 30) : '質問'}</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px;">${r.質問日時 ? new Date(r.質問日時).toLocaleDateString('ja-JP') : '日付未設定'}</div>
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getStatusColor(r.ステータス || '未回答')}; color: #fff; font-size: 11px;">${r.ステータス || '未回答'}</span>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    const colors = {
      '未回答': '#ff6a00',
      '回答済': '#2196f3',
      '資料公開待ち': '#ff9800',
      '公開済': '#4caf50'
    };
    return colors[status] || '#9fb0d1';
  }

  function showDetail(questionId) {
    const row = container.querySelector(`[data-id="${questionId}"]`);
    if (!row) return;

    const status = row.dataset.status || '未回答';
    const titleText = row.querySelector('div').textContent;
    const dateText = row.querySelectorAll('div')[1].textContent;

    container.querySelector("#detail-header").style.display = "block";
    container.querySelector("#no-selection").style.display = "none";
    container.querySelector("#detail-content").style.display = "block";
    container.querySelector("#detail-title").textContent = titleText;
    container.querySelector("#detail-status-badge").textContent = status;
    container.querySelector("#detail-status-badge").style.background = getStatusColor(status);
    container.querySelector("#detail-date").textContent = dateText;

    // ダミーデータ表示
    container.querySelector("#detail-question").textContent = "契約期間は通常どのような期間で設定されますか？また、延長の条件はありますか？";

    if (status === '公開済' || status === '回答済') {
      container.querySelector("#answer-section").style.display = "block";
      container.querySelector("#no-answer").style.display = "none";
      container.querySelector("#detail-answer").textContent = "契約期間は原則1年間です。延長を希望される場合は、契約満了の30日前までにご連絡ください。延長条件については別途協議させていただきます。";
      container.querySelector("#detail-answerer").textContent = "営業部 田中太郎";
      container.querySelector("#detail-answer-date").textContent = "2025-01-12";
      if (status === '公開済') {
        container.querySelector("#publish-info").style.display = "block";
        container.querySelector("#publish-date").textContent = "2025-01-12";
      } else {
        container.querySelector("#publish-info").style.display = "none";
      }
    } else {
      container.querySelector("#answer-section").style.display = "none";
      container.querySelector("#no-answer").style.display = "block";
    }

    if (status === '公開済') {
      container.querySelector("#materials-section").style.display = "block";
      container.querySelector("#no-materials").style.display = "none";
      container.querySelector("#history-section").style.display = "block";
      container.querySelector("#no-history").style.display = "none";
    } else {
      container.querySelector("#materials-section").style.display = "none";
      container.querySelector("#no-materials").style.display = "block";
      container.querySelector("#history-section").style.display = "none";
      container.querySelector("#no-history").style.display = "block";
    }
  }

  // ===== 2. 初期データ描画 =====
  const initialRows = tables[0]?.records || [
    { id: 'q-001', 質問内容: '契約期間について', 質問日時: '2025-01-15', ステータス: '未回答' },
    { id: 'q-002', 質問内容: '納期変更の条件', 質問日時: '2025-01-10', ステータス: '公開済' },
    { id: 'q-003', 質問内容: '成果物の品質基準', 質問日時: '2025-01-08', ステータス: '回答済' }
  ];
  renderQuestions(initialRows);

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const searchKeyword = container.querySelector("[data-testid='question-search']").value.toLowerCase();

    const rows = await window.aivicApi.list(0) || initialRows;
    const filtered = rows.filter(r => {
      const matchStatus = !statusFilter || (r.ステータス || '未回答') === statusFilter;
      const matchKeyword = !searchKeyword || JSON.stringify(r).toLowerCase().includes(searchKeyword);
      return matchStatus && matchKeyword;
    });
    renderQuestions(filtered);
  });

  // ===== 4. 質問行クリック =====
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".question-row");
    if (row) {
      showDetail(row.dataset.id);
    }
  });

  // ===== 5. ダウンロードボタン =====
  container.addEventListener("click", (e) => {
    const dlBtn = e.target.closest(".download-btn");
    if (dlBtn) {
      const materialId = dlBtn.dataset.id;
      alert(`資料 ${materialId} をダウンロードします`);
      // 実装: window.location.href = `${apiUrl}/download/${materialId}`;
    }
  });

  // ===== 6. CSV エクスポート =====
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0) || initialRows;
    const headers = ['質問ID', '質問内容', '質問日時', 'ステータス', '回答者', '回答日時'];
    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        r.id || '',
        `"${(r.質問内容 || '').replace(/"/g, '""')}"`,
        r.質問日時 || '',
        r.ステータス || '',
        r.回答者 || '',
        r.回答日時 || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv; charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `questions_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const contractTableIdx = tables.findIndex(t => t.tableName === '契約');
  const deliverableTableIdx = tables.findIndex(t => t.tableName === '成果物');
  const invoiceTableIdx = tables.findIndex(t => t.tableName === '請求書');
  const emailHistoryTableIdx = tables.findIndex(t => t.tableName === 'メール履歴');
  const notificationHistoryTableIdx = tables.findIndex(t => t.tableName === '通知履歴');

  // ============ 1. 契約テーブル再描画 ============
  function renderContracts(rows) {
    const tbody = container.querySelector('#contract-tbody');
