      tbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="5" style="padding: 1rem; text-align: center; color: var(--text-muted);">契約がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.08);" data-id="${r.id || ''}">
        <td style="padding: 0.5rem; color: var(--text);">${r.契約名 || ''}</td>
        <td style="padding: 0.5rem; color: var(--text);">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; background: ${getStatusBgColor(r.契約ステータス)}; color: #fff;">
            ${r.契約ステータス || ''}
          </span>
        </td>
        <td style="padding: 0.5rem; color: var(--text);">¥${(r.契約金額 || 0).toLocaleString()}</td>
        <td style="padding: 0.5rem; color: var(--text);">${formatDate(r.契約開始日)}</td>
        <td style="padding: 0.5rem; text-align: center;">
          <button class="action-btn secondary" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;" onclick="window.showScreen('scr-1781943478690');">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // ============ 2. 成果物テーブル再描画 ============
  function renderDeliverables(rows) {
    const tbody = container.querySelector('#deliverable-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="5" style="padding: 1rem; text-align: center; color: var(--text-muted);">成果物がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const statusColor = getDeliverableStatusColor(r.納期ステータス);
      return `
        <tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.08);" data-id="${r.id || ''}">
          <td style="padding: 0.5rem; color: var(--text);">${r.成果物名 || ''}</td>
          <td style="padding: 0.5rem; color: var(--text);">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; background: ${getStatusBgColor(r.ステータス)}; color: #fff;">
              ${r.ステータス || ''}
            </span>
          </td>
          <td style="padding: 0.5rem; color: var(--text);">${formatDate(r.納期)}</td>
          <td style="padding: 0.5rem;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; background: ${statusColor}; color: #fff;">
              ${r.納期ステータス || '未定'}
            </span>
          </td>
          <td style="padding: 0.5rem; text-align: center;">
            <button class="action-btn secondary" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;" onclick="window.showScreen('scr-1781943494360');">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ============ 3. 請求書テーブル再描画 ============
  function renderInvoices(rows) {
    const tbody = container.querySelector('#invoice-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted);">請求書がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.08);" data-id="${r.id || ''}">
        <td style="padding: 0.5rem; color: var(--text);">${r.請求書番号 || ''}</td>
        <td style="padding: 0.5rem; color: var(--text);">¥${(r.請求金額合計 || 0).toLocaleString()}</td>
        <td style="padding: 0.5rem; color: var(--text);">${formatDate(r.請求日)}</td>
        <td style="padding: 0.5rem; color: var(--text);">${formatDate(r.支払期限日)}</td>
        <td style="padding: 0.5rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; background: ${getInvoiceStatusColor(r.請求ステータス)}; color: #fff;">
            ${r.請求ステータス || ''}
          </span>
        </td>
        <td style="padding: 0.5rem; text-align: center;">
          <button class="action-btn secondary" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;" onclick="window.showScreen('scr-1781943508935');">ダウンロード</button>
        </td>
      </tr>
    `).join('');
  }

  // ============ 4. メール履歴表示 ============
  function renderEmailHistory(rows) {
    const container_el = container.querySelector('#email-history');
    if (!rows || rows.length === 0) {
      container_el.innerHTML = '<div style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">メール履歴がありません</div>';
      return;
    }
    const recent = rows.slice(0, 5);
    container_el.innerHTML = recent.map(r => `
      <div style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.08); font-size: 0.8125rem;">
        <div style="color: var(--text); font-weight: 500;">${r.件名 || ''}</div>
        <div style="color: var(--text-muted); font-size: 0.75rem;">
          ${r.送信者メールアドレス || ''} → ${r.受信者メールアドレス || ''} | ${formatDate(r.送受信日時)}
        </div>
      </div>
    `).join('');
  }

  // ============ 5. 通知履歴表示 ============
  function renderNotificationHistory(rows) {
    const container_el = container.querySelector('#notification-history');
    if (!rows || rows.length === 0) {
      container_el.innerHTML = '<div style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">通知がありません</div>';
      return;
    }
    const recent = rows.slice(0, 5);
    container_el.innerHTML = recent.map(r => `
      <div style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.08); font-size: 0.8125rem;">
        <div style="color: var(--text); font-weight: 500;">${r.通知タイトル || ''}</div>
        <div style="color: var(--text-muted); font-size: 0.75rem;">
          ${r.通知タイプ || ''} | ${formatDate(r.送信日時)}
          ${r.既読フラグ ? '' : '<span style="color: #ff6a00; margin-left: 0.5rem;">●未読</span>'}
        </div>
      </div>
    `).join('');
  }

  // ============ ユーティリティ関数 ============
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  function getStatusBgColor(status) {
    const colors = {
      '提案中': '#ff9800',
      '承認待ち': '#2196f3',
      '契約済': '#4caf50',
      '完了': '#8bc34a',
      '終了': '#9e9e9e',
      '進行中': '#2196f3',
      '計画中': '#9c27b0',
      '却下': '#f44336'
    };
    return colors[status] || '#757575';
  }

  function getDeliverableStatusColor(status) {
    const colors = {
      '予定通り': '#4caf50',
      '遅延': '#f44336',
      '完了': '#8bc34a',
      '早期納期': '#2196f3'
    };
    return colors[status] || '#757575';
  }

  function getInvoiceStatusColor(status) {
    const colors = {
      '未送付': '#9e9e9e',
      '送付済': '#2196f3',
      '支払済': '#4caf50',
      '期限超過': '#f44336'
    };
    return colors[status] || '#757575';
  }

  // ============ 初期データ読み込み ============
  if (contractTableIdx >= 0 && tables[contractTableIdx].records) {
    renderContracts(tables[contractTableIdx].records);
  }
  if (deliverableTableIdx >= 0 && tables[deliverableTableIdx].records) {
    renderDeliverables(tables[deliverableTableIdx].records);
  }
  if (invoiceTableIdx >= 0 && tables[invoiceTableIdx].records) {
    renderInvoices(tables[invoiceTableIdx].records);
  }
  if (emailHistoryTableIdx >= 0 && tables[emailHistoryTableIdx].records) {
    renderEmailHistory(tables[emailHistoryTableIdx].records);
  }
  if (notificationHistoryTableIdx >= 0 && tables[notificationHistoryTableIdx].records) {
    renderNotificationHistory(tables[notificationHistoryTableIdx].records);
  }

  // ============ ステータスフィルター ============
  const statusFilter = container.querySelector('[data-testid="contract-status-filter"]');
  if (statusFilter) {
    statusFilter.addEventListener('change', async (e) => {
      const selectedStatus = e.target.value;
      if (contractTableIdx >= 0) {
        const allRows = await window.aivicApi.list(contractTableIdx);
        const filtered = selectedStatus ? allRows.filter(r => r.契約ステータス === selectedStatus) : allRows;
        renderContracts(filtered);
      }
    });
  }
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractTableIdx = 0;
  const changeHistoryTableIdx = 1;
  const deliverableTableIdx = 2;
  const deadlineTableIdx = 3;

  // 初期データ
  const contracts = tables[contractTableIdx]?.records || [];
  const changeHistories = tables[changeHistoryTableIdx]?.records || [];
  const deliverables = tables[deliverableTableIdx]?.records || [];
  const deadlines = tables[deadlineTableIdx]?.records || [];

  // ============ 1. 再描画関数 ============

  function renderDeliverables(rows) {
    const tbody = container.querySelector("#deliverable-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="text-align: center; padding: 1rem; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 0.5rem; color: var(--text);">${r.成果物名 || '-'}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text-muted);">${r.納期 ? new Date(r.納期).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 0.5rem; text-align: center;"><span style="font-size: 0.75rem; padding: 0.25rem 0.5rem; border-radius: 0.2rem; background: ${r.ステータス === '完了' ? 'rgba(76,175,80,0.2)' : 'rgba(255,193,7,0.2)'}; color: ${r.ステータス === '完了' ? '#4caf50' : '#ffc107'};">${r.ステータス || '-'}</span></td>
      </tr>
    `).join('');
  }

  function renderDeadlines(rows) {
    const tbody = container.querySelector("#deadline-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="text-align: center; padding: 1rem; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 0.5rem; color: var(--text);">${r.項目 || '-'}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text-muted);">${r.予定納期日 ? new Date(r.予定納期日).toLocaleDateString('ja-JP') : '-'}</td>
        <td style="padding: 0.5rem; text-align: center;"><span style="font-size: 0.75rem; padding: 0.25rem 0.5rem; border-radius: 0.2rem; background: ${r.納期ステータス === '完了' ? 'rgba(76,175,80,0.2)' : r.納期ステータス === '遅延' ? 'rgba(244,67,54,0.2)' : 'rgba(33,150,243,0.2)'}; color: ${r.納期ステータス === '完了' ? '#4caf50' : r.納期ステータス === '遅延' ? '#f44336' : '#2196f3'};">${r.納期ステータス || '-'}</span></td>
      </tr>
    `).join('');
  }

  function renderChangeHistory(rows) {
    const historyDiv = container.querySelector("#change-history");
    if (!rows || rows.length === 0) {
      historyDiv.innerHTML = '<div style="text-align: center; padding: 1rem; color: var(--text-muted);">変更履歴なし</div>';
      return;
    }
    historyDiv.innerHTML = rows.map((r, idx) => `
      <div style="padding: 0.75rem; border-left: 2px solid var(--primary); margin-bottom: 0.5rem; background: rgba(0,0,0,0.1); border-radius: 0.2rem;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 0.25rem;">${r.変更種別 || '-'}</div>
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">${r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : '-'}</div>
        <div style="font-size: 0.8rem; color: var(--text); margin-bottom: 0.25rem;"><strong>理由:</strong> ${r.変更理由 || '-'}</div>
        <div style="font-size: 0.75rem; color: var(--text-muted);"><strong>ステータス:</strong> <span style="padding: 0.2rem 0.4rem; border-radius: 0.15rem; background: ${r.変更ステータス === '承認済' ? 'rgba(76,175,80,0.2)' : 'rgba(255,193,7,0.2)'}; color: ${r.変更ステータス === '承認済' ? '#4caf50' : '#ffc107'};">${r.変更ステータス || '-'}</span></div>
      </div>
    `).join('');
  }

  // ============ 2. 初期データ描画 ============
  renderDeliverables(deliverables);
  renderDeadlines(deadlines);
  renderChangeHistory(changeHistories);

  // 顧客企業名表示（サンプル）
  container.querySelector("#customer-name-display").textContent = "株式会社サンプル企業";

  // ============ 3. 契約書選択イベント ============
  container.querySelector("#contract-select").addEventListener("change", (e) => {
    const selectedId = e.target.value;
    const selected = contracts.find(c => c.契約書ID === selectedId || c.id === selectedId);
    if (selected) {
      const startDate = new Date(selected.契約開始日).toLocaleDateString('ja-JP');
      const endDate = new Date(selected.契約終了日).toLocaleDateString('ja-JP');
      container.querySelector("#contract-period").textContent = `${startDate} ～ ${endDate}`;
      container.querySelector("#contract-amount").textContent = `¥${(selected.契約金額 || 0).toLocaleString()}`;
      container.querySelector("#contract-status").textContent = selected.ステータス || '-';
      container.querySelector("#billing-contract-amount").textContent = `¥${(selected.契約金額 || 0).toLocaleString()}`;
    }
  });

  // ============ 4. ファイルアップロード ============
  const fileDropZone = container.querySelector("#file-drop-zone");
  const fileInput = container.querySelector("#file-input");
  const fileList = container.querySelector("#file-list");
  let uploadedFiles = [];

  fileDropZone.addEventListener("click", () => fileInput.click());
  fileDropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    fileDropZone.style.background = "rgba(0,0,0,0.3)";
  });
  fileDropZone.addEventListener("dragleave", () => {
    fileDropZone.style.background = "rgba(0,0,0,0.15)";
  });
  fileDropZone.addEventListener("drop", (e) => {
    e.preventDefault();
    fileDropZone.style.background = "rgba(0,0,0,0.15)";
    uploadedFiles = Array.from(e.dataTransfer.files);
    updateFileList();
  });
  fileInput.addEventListener("change", (e) => {
    uploadedFiles = Array.from(e.target.files);
    updateFileList();
  });

  function updateFileList() {
    fileList.innerHTML = uploadedFiles.map((f, idx) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 0.25rem 0; color: var(--text);">
        <span>${f.name}</span>
        <button class="remove-file-btn" data-idx="${idx}" style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 0.8rem;">削除</button>
      </div>
    `).join('');
    container.querySelectorAll(".remove-file-btn").forEach(btn => {
      btn.addEventListener("click", (e) => {
        uploadedFiles.splice(parseInt(e.target.dataset.idx), 1);
        updateFileList();
      });
    });
  }

  // ============ 5. 保存ボタン ============
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const contractId = container.querySelector("#contract-select").value;
    const agreementContent = container.querySelector("#agreement-textarea").value;
    const changeType = container.querySelector("#change-type").value;
    const changeContent = container.querySelector("#change-content").value;
    const changeReason = container.querySelector("#change-reason").value;
    const confirmed = container.querySelector("#confirm-checkbox").checked;

    if (!contractId) {
      alert("契約書を選択してください");
      return;
    }
    if (!confirmed) {
      alert("確認チェックボックスをチェックしてください");
      return;
    }

    // 合意内容を保存
    const agreementData = {
      contract_id: contractId,
      agreement_content: agreementContent,
      confirmed_at: new Date().toISOString(),
      confirmed: true
    };

    const saved = await window.aivicApi.save(contractTableIdx, agreementData);
    if (!saved) return;

    // 変更内容がある場合は変更履歴を保存
    if (changeType && changeContent) {
      const changeData = {
        contract_id: contractId,
        change_type: changeType,
        change_content: changeContent,
        change_reason: changeReason,
        change_status: "申請中",
        created_at: new Date().toISOString()
      };
      await window.aivicApi.save(changeHistoryTableIdx, changeData);
    }

    alert("合意内容を保存しました");
    // フォームをリセット
    container.querySelector("#agreement-textarea").value = "";
    container.querySelector("#change-type").value = "";
    container.querySelector("#change-content").value = "";
    container.querySelector("#change-reason").value = "";
    container.querySelector("#confirm-checkbox").checked = false;
    uploadedFiles = [];
    updateFileList();

    // 履歴を再読み込み
    const updated = await window.aivicApi.list(changeHistoryTableIdx);
    renderChangeHistory(updated || changeHistories);
  });

  // ============ 6. キャンセルボタン ============
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力内容を破棄しますか？")) {
      container.querySelector("#agreement-textarea").value = "";
      container.querySelector("#change-type").value = "";
      container.querySelector("#change-content").value = "";
      container.querySelector("#change-reason").value = "";
      container.querySelector("#confirm-checkbox").checked = false;
      uploadedFiles = [];
      updateFileList();
    }
  });

  // ============ 7. 提案資料リンク ============
  container.querySelector("#proposal-link").addEventListener("click", (e) => {
    e.preventDefault();
    alert("提案資料を表示します（実装例）");
  });
}
